#include <iostream>
#include <unordered_map>
#include <vector>

int main() {
    std::vector<int> ids = {1, 2};
    ids.push_back(3);
    for (const auto& id : ids) {
        std::cout << id << "\n";
    }

    std::unordered_map<std::string, int> portas;
    portas["http"] = 80;
    if (portas.find("http") != portas.end()) {
        std::cout << portas["http"] << "\n";
    }
    return 0;
}

